package com.company.tpm.employee; import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import static com.company.tpm.employee.EmployeeDtos.*;
@Service @Transactional public class EmployeeService{private final EmployeeRepository repo;private final EmployeeMapper mapper;public EmployeeService(EmployeeRepository r,EmployeeMapper m){repo=r;mapper=m;}public EmployeeResponse create(CreateEmployeeRequest d){repo.findByStaffId(d.staffId()).ifPresent(x->{throw new IllegalArgumentException("Staff ID already exists");});var e=new Employee(d.staffId(),d.fullName());e.update(d.fullName(),d.shift(),d.location());return mapper.toResponse(repo.save(e));}@Transactional(readOnly=true)public Page<EmployeeResponse>search(String q,Pageable p){Page<Employee>page=q==null||q.isBlank()?repo.findAll(p):repo.findByFullNameContainingIgnoreCaseOrStaffIdContainingIgnoreCase(q,q,p);return page.map(mapper::toResponse);}@Transactional(readOnly=true)public EmployeeResponse get(UUID id){return mapper.toResponse(repo.findById(id).orElseThrow(()->new IllegalArgumentException("Employee not found")));}public void deactivate(UUID id){repo.findById(id).orElseThrow(()->new IllegalArgumentException("Employee not found")).deactivate();}}
